#requires -Version 5.1
$ErrorActionPreference = 'Stop'
$ProjectRoot = (Get-Location).Path
$Required = @(
  'agent.py','core\document_manager.py','core\document_content_model.py',
  'core\evidence_manager.py','core\project_manager.py','modules\generic_uat_inspection.py',
  'docs\PROJECT_SETUP_GUIDE.md','.venv-scanner\Scripts\python.exe'
)
$Missing = @($Required | Where-Object { -not (Test-Path (Join-Path $ProjectRoot $_)) })
if ($Missing.Count -gt 0) { throw "Prasyarat tidak lengkap: $($Missing -join ', ')" }

Write-Host 'Memeriksa dependensi DOCX...' -ForegroundColor Cyan
$Python = Join-Path $ProjectRoot '.venv-scanner\Scripts\python.exe'
& $Python -c "import docx" 2>$null
if ($LASTEXITCODE -ne 0) {
  Write-Host 'Memasang python-docx pada .venv-scanner...'
  & $Python -m pip install python-docx
  if ($LASTEXITCODE -ne 0) { throw 'Instalasi python-docx gagal. Tidak ada source code yang diubah.' }
}

$Stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$Backup = Join-Path $ProjectRoot "backups\before_documentation_generator_$Stamp"
New-Item -ItemType Directory -Force -Path $Backup | Out-Null
$Targets = @('agent.py','docs\PROJECT_SETUP_GUIDE.md')
foreach ($relative in $Targets) {
  $source = Join-Path $ProjectRoot $relative
  $dest = Join-Path $Backup $relative
  New-Item -ItemType Directory -Force -Path (Split-Path $dest -Parent) | Out-Null
  Copy-Item $source $dest -Force
}
foreach ($relative in @('core\docx_renderer.py','core\document_viewer.py','modules\documentation_generator.py','tests\test_documentation_generator.py')) {
  $source = Join-Path $ProjectRoot $relative
  if (Test-Path $source) {
    $dest = Join-Path $Backup $relative
    New-Item -ItemType Directory -Force -Path (Split-Path $dest -Parent) | Out-Null
    Copy-Item $source $dest -Force
  }
}
Write-Host "Backup dibuat: $Backup" -ForegroundColor Green

$PayloadBase64 = ''
$PayloadZip = Join-Path $env:TEMP "documentation_generator_payload_$Stamp.zip"
$Stage = Join-Path $env:TEMP "documentation_generator_payload_$Stamp"
[IO.File]::WriteAllBytes($PayloadZip, [Convert]::FromBase64String($PayloadBase64))
New-Item -ItemType Directory -Force -Path $Stage | Out-Null
Expand-Archive -LiteralPath $PayloadZip -DestinationPath $Stage -Force
foreach ($relative in @('core\docx_renderer.py','core\document_viewer.py','modules\documentation_generator.py','tests\test_documentation_generator.py')) {
  $source = Join-Path $Stage $relative
  $dest = Join-Path $ProjectRoot $relative
  New-Item -ItemType Directory -Force -Path (Split-Path $dest -Parent) | Out-Null
  Copy-Item $source $dest -Force
}

$AgentPath = Join-Path $ProjectRoot 'agent.py'
$Agent = [IO.File]::ReadAllText($AgentPath, [Text.Encoding]::UTF8)
if ($Agent -notmatch 'from modules\.documentation_generator import generate_document_draft') {
  $ImportMarker = 'ROOT = Path(__file__).resolve().parent'
  if (-not $Agent.Contains($ImportMarker)) { throw 'Marker import agent.py tidak ditemukan; rollback manual dari backup diperlukan.' }
  $Agent = $Agent.Replace($ImportMarker, "from modules.documentation_generator import generate_document_draft`r`nfrom core.document_viewer import open_document_viewer`r`nfrom core.docx_renderer import render_approved_docx`r`n`r`n$ImportMarker")
}
if ($Agent -notmatch 'def run_documentation_generator\(') {
  $MainMarker = 'def main():'
  if (-not $Agent.Contains($MainMarker)) { throw 'Marker main() tidak ditemukan; rollback manual dari backup diperlukan.' }
  $FunctionText = @'
def run_documentation_generator(active_project_id):
    """Create/review/preview/export project documentation drafts."""
    from modules.documentation_generator import generate_document_draft, list_project_document_drafts
    from core.document_viewer import open_document_viewer
    from core.docx_renderer import render_approved_docx
    from core.document_manager import approve_document, get_document

    if not active_project_id:
        print("\nBelum ada proyek aktif.")
        active_project_id = select_active_project()
        if not active_project_id:
            print("Documentation Generator tidak dijalankan.")
            return None

    while True:
        print("\n--- DOCUMENTATION GENERATOR ---")
        print("Project ID:", active_project_id)
        print("1. Buat draft UAT")
        print("2. Buat draft User Guide Web")
        print("3. Buat draft User Guide CMS")
        print("4. Daftar dan review dokumen")
        print("5. Kembali")
        choice = input("Pilih menu: ").strip()
        if choice == "5":
            break
        if choice in ("1", "2", "3"):
            doc_type = {"1": "UAT", "2": "User_Guide_Web", "3": "User_Guide_CMS"}[choice]
            try:
                record = generate_document_draft(active_project_id, doc_type)
                manifest, version = record["manifest"], record["version"]
                doc_id = manifest["document_id"]
                print("\nDraft dibuat:", doc_id)
                print("Status:", version["status"])
                print("Bagian perlu ditinjau:", len(version.get("unverified_sections", [])))
                if version.get("unverified_sections"):
                    for item in version["unverified_sections"]:
                        print("-", item)
                if input("Buka A4 Print Preview? (y/n): ").strip().lower() == "y":
                    open_document_viewer(active_project_id, doc_id)
                print("DOCX final belum dibuat. Persetujuan hanya tersedia setelah seluruh bagian diverifikasi.")
            except Exception as error:
                print("\n[INFO] Draft tidak dapat dibuat:", error)
        elif choice == "4":
            docs = list_project_document_drafts(active_project_id)
            if not docs:
                print("Belum ada dokumen.")
                continue
            for index, item in enumerate(docs, 1):
                print(f"{index}. [{item['status']}] {item['document_type']} - {item['title']}")
                print("   ID:", item["document_id"], "| Versi:", item["current_version"])
            selected = input("Masukkan nomor dokumen (kosong untuk kembali): ").strip()
            if not selected:
                continue
            try:
                number = int(selected)
                item = docs[number - 1]
                doc_id = item["document_id"]
                action = input("Aksi: [1] Preview [2] Approve [3] Export DOCX [Enter] kembali: ").strip()
                if action == "1":
                    open_document_viewer(active_project_id, doc_id)
                elif action == "2":
                    current = get_document(active_project_id, doc_id)["version"]
                    if current.get("unverified_sections"):
                        print("Persetujuan ditolak: masih ada bagian yang belum diverifikasi.")
                    elif input("Konfirmasi: Anda telah memeriksa isi dan evidence? (y/n): ").strip().lower() == "y":
                        approved = approve_document(active_project_id, doc_id)
                        print("Versi disetujui:", approved["version"].get("status"))
                elif action == "3":
                    output = render_approved_docx(active_project_id, doc_id)
                    print("DOCX dibuat:", output)
            except (ValueError, IndexError, OSError, RuntimeError) as error:
                print("[INFO] Aksi dokumen tidak dapat diselesaikan:", error)
        else:
            print("Pilihan tidak valid.")
    return active_project_id
'@
  $Agent = $Agent.Replace($MainMarker, $FunctionText + $MainMarker)
}
if ($Agent -notmatch '7\. Documentation Generator') {
  $Agent = $Agent.Replace('    print("6. Jalankan Authentication Discovery")', '    print("6. Jalankan Authentication Discovery")' + "`r`n" + '    print("7. Documentation Generator")')
}
if ($Agent -notmatch 'elif choice == "7":') {
  $MenuMarker = '            elif choice == "8":'
  if (-not $Agent.Contains($MenuMarker)) { throw 'Marker menu 8 tidak ditemukan; rollback manual dari backup diperlukan.' }
  $Agent = $Agent.Replace($MenuMarker, '            elif choice == "7":' + "`r`n" + '                active_project_id = run_documentation_generator(active_project_id)' + "`r`n`r`n" + $MenuMarker)
}
[IO.File]::WriteAllText($AgentPath, $Agent, (New-Object System.Text.UTF8Encoding($false)))

$DocsPath = Join-Path $ProjectRoot 'docs\PROJECT_SETUP_GUIDE.md'
$Docs = [IO.File]::ReadAllText($DocsPath, [Text.Encoding]::UTF8)
if ($Docs -notmatch '## Documentation Generator, A4 Preview, dan DOCX Renderer') {
  $DocsAppend = @'

## Documentation Generator, A4 Preview, dan DOCX Renderer

Menu 7 menyediakan draft UAT, User Guide Web, dan User Guide CMS berdasarkan laporan inspeksi yang tersedia. Generator tidak mengarang langkah CMS atau hasil fungsional. UAT dan User Guide Web berstatus Needs Review sampai bagian yang belum terverifikasi diselesaikan; User Guide CMS berstatus Blocked bila laporan eksplorasi CMS belum tersedia.

A4 Print Preview menggunakan Tkinter dan bersifat read-only. DOCX Renderer menggunakan dependensi `python-docx` pada `.venv-scanner` dan hanya mengekspor versi berstatus APPROVED. Referensi gambar harus terdaftar di Evidence Manager dan hash SHA-256 diverifikasi sebelum dirender. File ekspor tidak menimpa DOCX versi yang sudah ada.

Alur: jalankan inspeksi yang relevan -> buat draft melalui menu 7 -> tinjau A4 Preview -> selesaikan bagian yang belum diverifikasi melalui proses QA -> setujui versi -> ekspor DOCX. Draft yang masih memiliki `unverified_sections` tidak dapat disetujui. Eksplorasi CMS belum diimplementasikan pada tahap ini, sehingga User Guide CMS tetap Blocked sampai sumber tersebut tersedia.

Catatan: Print Preview awal menyajikan representasi A4 berbasis halaman dan teks; kesamaan pagination/format dengan Microsoft Word belum dijamin dan harus diverifikasi secara visual pada dokumen nyata.
'@
  $Docs += $DocsAppend
  [IO.File]::WriteAllText($DocsPath, $Docs, (New-Object System.Text.UTF8Encoding($false)))
}

Write-Host "`nBatch implementation selesai menulis file." -ForegroundColor Green
Write-Host 'Backup:' $Backup
Write-Host "`nMenjalankan pemeriksaan syntax dan tes terfokus..."
& $Python -m py_compile .\agent.py .\core\docx_renderer.py .\core\document_viewer.py .\modules\documentation_generator.py .\tests\test_documentation_generator.py
if ($LASTEXITCODE -ne 0) { throw 'Syntax check gagal. Pertahankan backup dan kirim error untuk diagnosis.' }
& $Python -m unittest discover -s tests -p test_documentation_generator.py -v
if ($LASTEXITCODE -ne 0) { throw 'Tes Documentation Generator gagal. Jangan lanjut ke full regression.' }
Write-Host "`nImplementasi dan tes terfokus selesai. Full regression belum dijalankan." -ForegroundColor Green
